mapper.select:
select
videos.*,
types.type_name
from videos videos
left join types types on videos.type_id = types.id

    and videos.id = #{id}
    and videos.title like concat('%',#{title},'%')
    and videos.cover = #{cover}
    and videos.type_id = #{typeId}
    and videos.see_num = #{seeNum}
    and videos.create_time = #{createTime}
    and videos.video_url = #{videoUrl}
    and types.type_name like concat('%',#{typeName},'%')


    limit #{current},#{pageSize}

select count(*) from videos videos
left join types types on videos.type_id = types.id

    and videos.id = #{id}
    and videos.title like concat('%',#{title},'%')
    and videos.cover = #{cover}
    and videos.type_id = #{typeId}
    and videos.see_num = #{seeNum}
    and videos.create_time = #{createTime}
    and videos.video_url = #{videoUrl}
    and types.type_name like concat('%',#{typeName},'%')
